package kr.workbench;
import javax.swing.*;import javax.swing.text.*;import java.awt.*;
import burp.api.montoya.MontoyaApi;import burp.api.montoya.http.message.HttpRequestResponse;import java.util.List;
final class StructuredComparePanel extends JPanel {
 final JTextArea leftInput=new JTextArea(),rightInput=new JTextArea(),leftView=new JTextArea(),rightView=new JTextArea();final JCheckBox formatted=new JCheckBox("데이터 정렬",true);final JLabel status=new JLabel("양쪽에 데이터를 붙여넣고 비교하세요.");final JButton previous=new JButton("←"),next=new JButton("→");final CardLayout cards=new CardLayout();final JPanel content=new JPanel(cards);StructuredCompare.Result result;int current=-1;boolean showing;
 final MontoyaApi api;final JLabel sourceStatus=new JLabel("원본 연결 없음 · 붙여넣은 데이터만으로는 원본 증거를 만들지 않습니다.");final JButton captureEvidence=new JButton("연결 원본 2개 → 증거"),loadLeft=new JButton("선택 트래픽 → 왼쪽 응답"),loadRight=new JButton("선택 트래픽 → 오른쪽 응답");
 java.util.function.Supplier<List<HttpRequestResponse>> selectedTraffic=List::of;java.util.function.BiConsumer<List<HttpRequestResponse>,String> evidenceSink=(packets,note)->{throw new IllegalArgumentException("증거 기능 준비 중");};HttpRequestResponse leftSource,rightSource;boolean loadingSource;
 StructuredComparePanel(){this(null);}
 StructuredComparePanel(MontoyaApi api){super(new BorderLayout(8,8));this.api=api;setBorder(BorderFactory.createEmptyBorder(8,8,8,8));JButton compare=new JButton("비교"),edit=new JButton("입력으로"),clear=new JButton("초기화");WorkbenchUi.primary(compare);previous.setToolTipText("이전 차이");next.setToolTipText("다음 차이");previous.setEnabled(false);next.setEnabled(false);leftView.setEditable(false);rightView.setEditable(false);for(JTextArea a:new JTextArea[]{leftInput,rightInput,leftView,rightView}){a.setLineWrap(false);a.setFont(WorkbenchUi.textFont("가나다"));}content.add(pair(leftInput,rightInput),"input");content.add(pair(leftView,rightView),"result");add(WorkbenchUi.header("데이터 비교","JSON · XML · HTTP 패킷을 정렬해서 비교 · 붉은색: 왼쪽 차이 / 초록색: 오른쪽 차이",TargetWindow.options(WorkbenchUi.row(compare,edit,clear,formatted,previous,next),WorkbenchUi.row(loadLeft,loadRight,captureEvidence),sourceStatus)),BorderLayout.NORTH);add(content);add(status,BorderLayout.SOUTH);loadLeft.addActionListener(e->sourceAction(()->loadSelected(true)));loadRight.addActionListener(e->sourceAction(()->loadSelected(false)));captureEvidence.addActionListener(e->sourceAction(this::captureEvidence));captureEvidence.setEnabled(false);watchInput(leftInput,true);watchInput(rightInput,false);compare.addActionListener(e->compare());edit.addActionListener(e->{showing=false;cards.show(content,"input");});clear.addActionListener(e->{leftInput.setText("");rightInput.setText("");leftView.setText("");rightView.setText("");result=null;current=-1;showing=false;cards.show(content,"input");previous.setEnabled(false);next.setEnabled(false);status.setText("양쪽에 데이터를 붙여넣고 비교하세요.");});formatted.addActionListener(e->{if(showing)compare();});previous.addActionListener(e->move(-1));next.addActionListener(e->move(1));WorkbenchUi.style(this);}
 void sourceAction(Runnable action){try{action.run();}catch(Exception ex){status.setText(ex.getMessage());}}
 void watchInput(JTextArea input,boolean left){input.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){changed();}public void removeUpdate(javax.swing.event.DocumentEvent e){changed();}public void changedUpdate(javax.swing.event.DocumentEvent e){changed();}void changed(){if(loadingSource)return;if(left)leftSource=null;else rightSource=null;sourceSummary();}});}
 void sourceSummary(){sourceStatus.setText("왼쪽: "+sourceName(leftSource)+" · 오른쪽: "+sourceName(rightSource)+" · 입력 편집 시 해당 원본 연결 해제");captureEvidence.setEnabled(leftSource!=null&&rightSource!=null);}
 static String sourceName(HttpRequestResponse rr){return rr==null?"원본 연결 없음":rr.request().method()+" "+Core.safeUrl(rr.request().url())+" [HTTP "+rr.response().statusCode()+"]";}
 void loadSelected(boolean left){List<HttpRequestResponse> packets=selectedTraffic.get();if(packets.size()!=1)throw new IllegalArgumentException("트래픽에서 원본 요청 1개를 선택하세요.");loadSource(left,packets.get(0));}
 void loadSource(boolean left,HttpRequestResponse rr){EvidenceLinks.checked(api,List.of(rr));loadingSource=true;try{if(left){leftInput.setText(rr.response().toString());leftSource=rr;}else{rightInput.setText(rr.response().toString());rightSource=rr;}}finally{loadingSource=false;}showing=false;cards.show(content,"input");sourceSummary();status.setText("원본 응답 연결 · 전송 없이 가져옴 · 데이터 비교는 취약점 확정이 아닙니다.");}
 void captureEvidence(){if(leftSource==null||rightSource==null)throw new IllegalArgumentException("양쪽에 원본 트래픽을 연결하세요. 편집한 입력은 다시 가져와야 합니다.");var packets=EvidenceLinks.checked(api,List.of(leftSource,rightSource));var compared=StructuredCompare.compare(leftInput.getText(),rightInput.getText(),formatted.isSelected());int changes=compared.changes().size();evidenceSink.accept(packets,"데이터 비교 · 왼쪽/오른쪽 원본 순서 · 표시 차이 "+changes+"곳"+(compared.limited()?" · 비교 표시 제한(64 KiB/1,500줄) · 전체 응답 차이 수가 아님":"")+" · 차이는 취약점 확정 아님");status.setText("좌/우 원본 패킷 2개 증거 전달 · 저장은 점검 지원에서 실행하세요.");}
 void clearSources(){leftSource=null;rightSource=null;leftInput.setText("");rightInput.setText("");leftView.setText("");rightView.setText("");result=null;current=-1;showing=false;previous.setEnabled(false);next.setEnabled(false);cards.show(content,"input");sourceSummary();}
 JPanel pair(JTextArea a,JTextArea b){JSplitPane split=WorkbenchUi.split(JSplitPane.HORIZONTAL_SPLIT,WorkbenchUi.card("왼쪽 데이터",new JScrollPane(a)),WorkbenchUi.card("오른쪽 데이터",new JScrollPane(b)),.5);split.setResizeWeight(.5);split.setDividerLocation(.5);split.setName("wb.compare.sides");JPanel p=new JPanel(new BorderLayout());p.add(split);return p;}
 void compare(){result=StructuredCompare.compare(leftInput.getText(),rightInput.getText(),formatted.isSelected());leftView.setText(result.left());rightView.setText(result.right());leftView.getHighlighter().removeAllHighlights();rightView.getHighlighter().removeAllHighlights();for(var c:result.changes()){highlight(leftView,c.leftStart(),c.leftEnd(),WorkbenchUi.dark()?new Color(100,43,50):new Color(255,190,190));highlight(rightView,c.rightStart(),c.rightEnd(),WorkbenchUi.dark()?new Color(31,82,53):new Color(175,230,190));}current=-1;showing=true;cards.show(content,"result");previous.setEnabled(!result.changes().isEmpty());next.setEnabled(!result.changes().isEmpty());status.setText("차이 "+result.changes().size()+"곳"+(result.limited()?" · 표시 제한: 입력 64 KiB / 1,500줄":" · 빈 줄은 차이 위치를 맞추기 위한 표시입니다."));leftView.setCaretPosition(0);rightView.setCaretPosition(0);}
 void move(int step){if(result==null||result.changes().isEmpty())return;current=current<0?(step>0?0:result.changes().size()-1):Math.floorMod(current+step,result.changes().size());var c=result.changes().get(current);leftView.setCaretPosition(c.leftStart());rightView.setCaretPosition(c.rightStart());status.setText("차이 "+(current+1)+" / "+result.changes().size()+(result.limited()?" · 표시 제한 적용":""));}
 static void highlight(JTextArea area,int start,int end,Color color){try{if(end>start)area.getHighlighter().addHighlight(start,end,new DefaultHighlighter.DefaultHighlightPainter(color));}catch(BadLocationException ignored){}}
}
